import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef, useId } from "vue";
import { Annotate } from "@/components/ui/annotate";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogMedia, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import { ButtonGroup } from "@/components/ui/button-group";
import { Icon } from "@/components/ui/icon";
import { InputControl } from "@/components/ui/input";
import { Notebook, NotebookPage, NotebookTitle } from "@/components/ui/notebook";
import { Paper } from "@/components/ui/paper";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tally } from "@/components/ui/tally";
import { TextareaControl } from "@/components/ui/textarea";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { MARKS, toggleMark, wordCount, type MarkKind, type Note } from "@/blocks/notes-app/components/notes-app-data";
import { MARK_LOOK, NotesAppMarked } from "@/blocks/notes-app/components/notes-app-marked";
import { cn } from "@/lib/utils";
export type EditorMode = "page" | "write";
type Props = {
  note: Note;
  notebookName: string;
  mode: EditorMode;
  onModeChange: (mode: EditorMode) => void;
  onChange: (patch: Partial<Pick<Note, "title" | "body" | "reads">>) => void;
  onDelete: () => void;
  onBack: () => void;
  className?: string;
};
const MARK_ORDER: MarkKind[] = ["highlight", "underline", "circle", "strike"];
export const NotesAppEditor = defineUi<Props>("NotesAppEditor", ["note", "notebookName", "mode", "onModeChange", "onChange", "onDelete", "onBack", "class"], (_props, {
  slots: _slots
}) => {
  const note = computed(() => _props["note"]);
  const notebookName = computed(() => _props["notebookName"]);
  const mode = computed(() => _props["mode"]);
  const onModeChange = computed(() => _props["onModeChange"]);
  const onChange = computed(() => _props["onChange"]);
  const onDelete = computed(() => _props["onDelete"]);
  const onBack = computed(() => _props["onBack"]);
  const className = computed(() => _props["class"]);
  const area = shallowRef<HTMLTextAreaElement | null>(null);
  const title = shallowRef<HTMLInputElement | null>(null);
  const restore = shallowRef<{
    start: number;
    end: number;
  } | null | null>(null);
  const focusSoon = shallowRef(initialState(false));
  const setFocusSoon = stateSetter(focusSoon);
  const hint = useId();
  watchDependencies(() => {
    if (mode.value === "write" && !note.value.title && !note.value.body) title.value?.focus();
  }, () => [], false);
  watchDependencies(() => {
    const el = area.value;
    if (!el) return;
    if (restore.value) {
      el.setSelectionRange(restore.value.start, restore.value.end);
      restore.value = null;
    }
    if (focusSoon.value) {
      el.focus();
      setFocusSoon(false);
    }
  }, undefined, true);
  const mark = computed(() => (kind: MarkKind) => {
    if (mode.value !== "write") {
      onModeChange.value("write");
      setFocusSoon(true);
      return;
    }
    const el = area.value;
    if (!el) return;
    const next = toggleMark(el.value, el.selectionStart, el.selectionEnd, kind);
    if (!next) {
      el.focus();
      return;
    }
    restore.value = {
      start: next.start,
      end: next.end
    };
    onChange.value({
      body: next.text
    });
    setFocusSoon(true);
  });
  return () => {
    return <section aria-label="Editor" data-slot="notes-app-editor" tabindex={-1} class={cn("flex min-h-0 flex-col gap-3 outline-none", className.value)}>
      <TooltipProvider delayDuration={300}>
        <Paper stock="slip" tilt={-0.2} seed="notes-toolbar" class="flex flex-wrap items-center gap-x-3 gap-y-2 px-3 py-2">
          <Button variant="ghost" size="icon-sm" class="@4xl/notes:hidden" onClick={onBack.value} aria-label="Back to notes">
            <Icon name="arrow-left" class="rtl:-scale-x-100" />
          </Button>
          <ToggleGroup type="single" size="sm" variant="outline" value={mode.value} onValueChange={v => v && onModeChange.value(v as EditorMode)} aria-label="View">
            <ToggleGroupItem value="page">Page</ToggleGroupItem>
            <ToggleGroupItem value="write">Write</ToggleGroupItem>
          </ToggleGroup>
          <ButtonGroup aria-label="Marks">
            {MARK_ORDER.map(kind => {
              const look = MARK_LOOK[kind];
              return <Tooltip key={kind}>
                  <TooltipTrigger asChild>
                    <Button type="button" variant="outline" size="sm" aria-label={MARKS[kind].label} aria-describedby={hint} onMousedown={e => e.preventDefault()} onClick={() => mark.value(kind)}>
                      <Annotate type={look.type} color={look.color} kind={look.kind} seed={`tool-${kind}`} class="px-1">
                        Aa
                      </Annotate>
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent seed={`tip-${kind}`}>{MARKS[kind].label}</TooltipContent>
                </Tooltip>;
            })}
          </ButtonGroup>
          <AlertDialog>
            <AlertDialogTrigger asChild>
              <Button variant="ghost" size="icon-sm" class="ms-auto" aria-label="Tear this page out">
                <Icon name="trash" />
              </Button>
            </AlertDialogTrigger>
            <AlertDialogContent tone="danger" seed="tear-out">
              <AlertDialogHeader>
                <AlertDialogMedia tone="danger">
                  <Icon name="trash" />
                </AlertDialogMedia>
                <AlertDialogTitle>Tear this page out?</AlertDialogTitle>
                <AlertDialogDescription>“{note.value.title || "Untitled"}” goes in the bin with everything written on it.</AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Keep it</AlertDialogCancel>
                <AlertDialogAction variant="destructive" onClick={onDelete.value}>
                  Tear it out
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
          <p id={hint} class="basis-full text-sm text-muted-foreground">
            Select some words in Write, then press a mark. Press it again to take it off.
          </p>
        </Paper>
      </TooltipProvider>

      <ScrollArea class="min-h-0 flex-1" bleed>
        <Notebook as="div" binding="spiral" pages={2} tilt={0.15} seed={`notes-page`} class="ms-3 min-h-[30rem]">
          <NotebookPage aria-label={note.value.title || "Untitled"}>
            <NotebookTitle>
              {mode.value === "write" ? <InputControl ref={title} aria-label="Title" placeholder="Untitled" value={note.value.title} onChange={(e: Event) => onChange.value({
                title: (e.target as HTMLInputElement).value
              })} class="block h-7 w-full bg-transparent p-0 font-script text-[1.75rem] leading-7 font-bold text-ink-you outline-offset-2 placeholder:text-pencil-text focus-visible:outline-2 focus-visible:outline-focus" /> : note.value.title || "Untitled"}
            </NotebookTitle>
            {mode.value === "write" ? <TextareaControl ref={area} aria-label="Note" aria-describedby={hint} placeholder="Start writing on the first line." rows={10} value={note.value.body} onChange={(e: Event) => onChange.value({
              body: (e.target as HTMLTextAreaElement).value
            })} class="block min-h-70 w-full resize-none p-0 text-[17px] leading-7 text-ink-you" /> : <div onDblclick={() => onModeChange.value("write")}>
                <NotesAppMarked body={note.value.body} seed={note.value.id} />
              </div>}
            <div class="mt-7 flex h-7 items-center gap-3 text-sm text-muted-foreground">
              <span>times I have read it</span>
              <Tally count={note.value.reads} size="md" label={`Read ${note.value.reads} times`} seed={`${note.value.id}-reads`} />
              <Button size="xs" variant="ghost" onClick={() => onChange.value({
                reads: note.value.reads + 1
              })} aria-label="Count another read">
                +1
              </Button>
            </div>
            <p class="ll-num h-7 text-sm text-muted-foreground">
              {wordCount(note.value.body)} words · {notebookName.value}
            </p>
          </NotebookPage>
        </Notebook>
      </ScrollArea>
    </section>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, Fragment } from "vue";
import { Annotate, type AnnotateType } from "@/components/ui/annotate";
import { parseLine, type MarkKind } from "@/blocks/notes-app/components/notes-app-data";
export const MARK_LOOK: Record<MarkKind, {
  type: AnnotateType;
  color: "yellow" | "blue" | "red";
  kind?: "wavy";
}> = {
  highlight: {
    type: "highlight" as const,
    color: "yellow" as const
  },
  underline: {
    type: "underline" as const,
    color: "blue" as const,
    kind: "wavy" as const
  },
  circle: {
    type: "circle" as const,
    color: "red" as const
  },
  strike: {
    type: "strike-through" as const,
    color: "red" as const
  }
};
export const NotesAppMarked = defineUi<{
  body: string;
  seed: string;
}>("NotesAppMarked", ["body", "seed"], (_props, {
  slots: _slots
}) => {
  const body = computed(() => _props["body"]);
  const seed = computed(() => _props["seed"]);
  return () => {
    return <div class="text-[17px] leading-7 wrap-break-word">
      {body.value.split("\n").map((line, i) => <div key={i} class="min-h-7">
          {parseLine(line).map((piece, j) => {
          if (!piece.mark) return <Fragment key={j}>{piece.text}</Fragment>;
          const look = MARK_LOOK[piece.mark];
          return <Annotate key={j} type={look.type} color={look.color} kind={look.kind} seed={`${seed.value}:${i}:${j}`}>
                {piece.text}
              </Annotate>;
        })}
        </div>)}
    </div>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId, shallowRef } from "vue";
import { Button } from "@/components/ui/button";
import { Empty, EmptyContent, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { Icon } from "@/components/ui/icon";
import { IndexCard, IndexCardContent, IndexCardFooter, IndexCardHeader, IndexCardTitle } from "@/components/ui/index-card";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { Paper } from "@/components/ui/paper";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ALL, NOTEBOOKS, stripMarks, type Note } from "@/blocks/notes-app/components/notes-app-data";
import { cn } from "@/lib/utils";
type Props = {
  notes: Note[];
  notebook: string;
  onNotebookChange: (id: string) => void;
  selectedId: string | null;
  onSelect: (id: string) => void;
  onNew: () => void;
  headingRef?: UI.Ref<HTMLHeadingElement>;
  className?: string;
};
const inNotebook = (notes: Note[], id: string) => id === ALL ? notes : notes.filter(n => n.notebook === id);
const nameOf = (id: string) => NOTEBOOKS.find(n => n.id === id)?.name ?? id;
const NoteCard = defineUi<{
  note: Note;
  selected: boolean;
  onSelect: () => void;
}>("NoteCard", ["note", "selected", "onSelect"], (_props, {
  slots: _slots
}) => {
  const note = computed(() => _props["note"]);
  const selected = computed(() => _props["selected"]);
  const onSelect = computed(() => _props["onSelect"]);
  const title = computed(() => note.value.title || "Untitled");
  return () => {
    return <li>
      <IndexCard seed={note.value.id} flag={selected.value ? "lemon" as const : false} class="min-h-0 max-w-none px-4">
        <IndexCardHeader>
          <IndexCardTitle role="heading" aria-level={3} class="text-2xl @max-md/notes:text-[1.3rem]">
            {title.value}
          </IndexCardTitle>
        </IndexCardHeader>
        <IndexCardContent class="line-clamp-2 text-[15px]">{stripMarks(note.value.body).replace(/\s+/g, " ").trim() || "Nothing written yet."}</IndexCardContent>
        <IndexCardFooter>
          <span class="truncate">{nameOf(note.value.notebook)}</span>
          <span class="shrink-0">{note.value.updated}</span>
        </IndexCardFooter>
        <button type="button" aria-label={`Open ${title.value}`} aria-current={selected.value ? "true" as const : undefined} onClick={onSelect.value} class="absolute inset-0 z-10 cursor-pointer outline-offset-4 focus-visible:outline-2 focus-visible:outline-focus" />
      </IndexCard>
    </li>;
  };
});
export const NotesAppNoteList = defineUi<Props>("NotesAppNoteList", ["notes", "notebook", "onNotebookChange", "selectedId", "onSelect", "onNew", "headingRef", "class"], (_props, {
  slots: _slots
}) => {
  const notes = computed(() => _props["notes"]);
  const notebook = computed(() => _props["notebook"]);
  const onNotebookChange = computed(() => _props["onNotebookChange"]);
  const selectedId = computed(() => _props["selectedId"]);
  const onSelect = computed(() => _props["onSelect"]);
  const onNew = computed(() => _props["onNew"]);
  const headingRef = computed(() => _props["headingRef"]);
  const className = computed(() => _props["class"]);
  const heading = useId();
  const query = shallowRef(initialState(""));
  const setQuery = stateSetter(query);
  const q = computed(() => query.value.trim().toLowerCase());
  return () => {
    return <Paper as="aside" stock="pad" rules="none" tilt={-0.3} fastener="binder-clip" seed="notes-shelf" aria-labelledby={heading} data-slot="notes-app-list" class={cn("flex min-h-0 flex-col gap-3 pt-6 pb-3", className.value)}>
      <div class="flex items-center justify-between gap-3 px-4">
        <h2 id={heading} ref={headingRef.value} tabindex={-1} class="font-script text-[1.7rem] leading-none font-semibold outline-offset-4 focus-visible:outline-2 focus-visible:outline-focus">
          Notes
        </h2>
        <Button size="sm" onClick={onNew.value}>
          <Icon name="plus" />
          New page
        </Button>
      </div>
      <div class="px-4">
        <InputGroup>
          <InputGroupAddon>
            <Icon name="search" />
          </InputGroupAddon>
          <InputGroupInput type="search" placeholder="Search this notebook" aria-label="Search this notebook" value={query.value} onChange={(e: Event) => setQuery((e.target as HTMLInputElement).value)} />
        </InputGroup>
      </div>

      <Tabs orientation="vertical" value={notebook.value} onValueChange={onNotebookChange.value} class="min-h-0 flex-1 gap-2 ps-3 pe-1">
        <TabsList aria-label="Notebooks" class="w-28 shrink-0">
          {NOTEBOOKS.map(nb => <TabsTrigger key={nb.id} value={nb.id} seed={`nb-${nb.id}`}>
              {nb.name}
              <span class="ll-num ms-auto text-xs font-normal">{inNotebook(notes.value, nb.id).length}</span>
            </TabsTrigger>)}
        </TabsList>
        {NOTEBOOKS.map(nb => {
          const rows = inNotebook(notes.value, nb.id).filter(n => !q.value || `${n.title} ${stripMarks(n.body)}`.toLowerCase().includes(q.value));
          return <TabsContent key={nb.id} value={nb.id} class="min-h-0 min-w-0">
              <ScrollArea class="h-full" bleed>
                {rows.length === 0 ? <Empty seed={`empty-${nb.id}`} class="p-2 md:p-4">
                    <EmptyHeader>
                      <EmptyMedia pose={q.value ? "search" as const : "sleep" as const} size={88} />
                      <EmptyTitle>{q.value ? "No page says that" as const : "Nothing here yet" as const}</EmptyTitle>
                      <EmptyDescription>{q.value ? `Try a shorter word than “${query.value.trim()}”.` : `${nb.name} is a clean page waiting for a first line.`}</EmptyDescription>
                    </EmptyHeader>
                    {q.value ? null : <EmptyContent>
                        <Button size="sm" onClick={onNew.value}>
                          Start a page
                        </Button>
                      </EmptyContent>}
                  </Empty> : <ul aria-label={`${nb.name} pages`} class="grid grid-cols-1 gap-4">
                    {rows.map(n => <NoteCard key={n.id} note={n} selected={n.id === selectedId.value} onSelect={() => onSelect.value(n.id)} />)}
                  </ul>}
              </ScrollArea>
            </TabsContent>;
        })}
      </Tabs>
    </Paper>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, shallowRef } from "vue";
import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty";
import { Paper } from "@/components/ui/paper";
import { ALL, FEATURED, NOTEBOOKS, NOTES, type Note } from "@/blocks/notes-app/components/notes-app-data";
import { NotesAppEditor, type EditorMode } from "@/blocks/notes-app/components/notes-app-editor";
import { NotesAppNoteList } from "@/blocks/notes-app/components/notes-app-note-list";
import { cn } from "@/lib/utils";
type Props = {
  className?: string;
  defaultNotes?: Note[];
  onNotesChange?: (notes: Note[]) => void;
};
const NotesApp = defineUi<Props>("NotesApp", ["class", "defaultNotes", "onNotesChange"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const defaultNotes = computed(() => _props["defaultNotes"] === undefined ? NOTES : _props["defaultNotes"]);
  const onNotesChange = computed(() => _props["onNotesChange"]);
  const notes = shallowRef<Note[]>(initialState(defaultNotes.value));
  const setNotes = stateSetter(notes);
  const commit = computed(() => (next: Note[]) => {
    setNotes(next);
    onNotesChange.value?.(next);
  });
  const notebook = shallowRef(initialState(ALL));
  const setNotebook = stateSetter(notebook);
  const selectedId = shallowRef<string | null>(initialState(defaultNotes.value.some(n => n.id === FEATURED) ? FEATURED : defaultNotes.value[0]?.id ?? null));
  const setSelectedId = stateSetter(selectedId);
  const mode = shallowRef<EditorMode>(initialState("page"));
  const setMode = stateSetter(mode);
  const view = shallowRef<"list" | "editor">(initialState("list"));
  const setView = stateSetter(view);
  const counter = shallowRef(0);
  const shelf = shallowRef<HTMLHeadingElement | null>(null);
  const handBack = shallowRef(initialState(false));
  const setHandBack = stateSetter(handBack);
  const note = computed(() => notes.value.find(n => n.id === selectedId.value));
  const notebookName = computed(() => NOTEBOOKS.find(nb => nb.id === note.value?.notebook)?.name ?? "");
  watchDependencies(() => {
    if (!handBack.value) return;
    shelf.value?.focus();
    setHandBack(false);
  }, () => [handBack.value], false);
  const grid = shallowRef<HTMLDivElement | null>(null);
  const shown = shallowRef(view.value);
  watchDependencies(() => {
    if (shown.value === view.value) return;
    shown.value = view.value;
    if (handBack.value) return;
    const gone = grid.value?.querySelector<HTMLElement>(view.value === "editor" ? "[data-slot=notes-app-list]" as const : "[data-slot=notes-app-editor]" as const);
    if (!gone || getComputedStyle(gone).display !== "none") return;
    const target = view.value === "editor" ? grid.value?.querySelector<HTMLElement>("[data-slot=notes-app-editor]") : grid.value?.querySelector<HTMLElement>("[data-slot=notes-app-list] [aria-current=true]") ?? shelf.value;
    target?.focus();
  }, () => [view.value, handBack.value], false);
  const open = computed(() => (id: string) => {
    setSelectedId(id);
    setMode("page");
    setView("editor");
  });
  const create = computed(() => () => {
    const id = `page-${counter.value++}`;
    const home = notebook.value === ALL ? "scraps" as const : notebook.value;
    commit.value([{
      id,
      notebook: home,
      title: "" as const,
      body: "" as const,
      updated: "just now" as const,
      reads: 0
    }, ...notes.value]);
    setSelectedId(id);
    setMode("write");
    setView("editor");
  });
  const change = computed(() => (patch: Partial<Pick<Note, "title" | "body" | "reads">>) => commit.value(notes.value.map(n => n.id === selectedId.value ? {
    ...n,
    ...patch,
    updated: "just now" as const
  } : n)));
  const remove = computed(() => () => {
    const rest = notes.value.filter(n => n.id !== selectedId.value);
    commit.value(rest);
    setSelectedId(rest.find(n => notebook.value === ALL || n.notebook === notebook.value)?.id ?? null);
    setMode("page");
    setView("list");
    setHandBack(true);
  });
  return () => {
    return <div class="@container/notes w-full">
      <div ref={grid} data-slot="notes-app" data-view={view.value} class={cn("group/notes grid h-[48rem] max-h-[100svh] min-h-[32rem] w-full grid-cols-1 grid-rows-[minmax(0,1fr)] gap-6 p-4 pt-10 @4xl/notes:grid-cols-[minmax(20rem,24rem)_minmax(0,1fr)] @4xl/notes:p-6 @4xl/notes:pt-12", className.value)}>
        <NotesAppNoteList notes={notes.value} notebook={notebook.value} onNotebookChange={setNotebook} selectedId={selectedId.value} onSelect={open.value} onNew={create.value} headingRef={shelf} class="group-data-[view=editor]/notes:@max-4xl/notes:hidden" />
        {note.value ? <NotesAppEditor key={note.value.id} note={note.value} notebookName={notebookName.value} mode={mode.value} onModeChange={setMode} onChange={change.value} onDelete={remove.value} onBack={() => setView("list")} class="group-data-[view=list]/notes:@max-4xl/notes:hidden" /> : <Paper as="section" stock="card" aria-label="Editor" class="grid place-items-center group-data-[view=list]/notes:@max-4xl/notes:hidden">
            <Empty seed="no-page">
              <EmptyHeader>
                <EmptyMedia pose="idle" size={104} />
                <EmptyTitle>Pick a page</EmptyTitle>
                <EmptyDescription>Open one from the shelf, or start a new page with the button up there.</EmptyDescription>
              </EmptyHeader>
            </Empty>
          </Paper>}
      </div>
    </div>;
  };
});
export default NotesApp;
